#include <iostream>
#include <vector>
#include <algorithm>
int main(){int n;if(!(std::cin>>n)||n<0||n>10000)return 0;std::vector<int>a(n);for(int&x:a)if(!(std::cin>>x))return 0;for(std::size_t i=0;i<a.size();++i){std::size_t k=i;for(std::size_t j=i+1;j<a.size();++j)if(a[j]<a[k])k=j;std::swap(a[i],a[k]);}for(std::size_t i=0;i<a.size();++i)std::cout<<(i?" ":"")<<a[i];std::cout<<"\n";}
